code.css:
/* Search replaces the title bar rather than sitting under it. */
.search-bar {
  position: absolute;
  inset: 0 0 auto 0;
  height: 124px;
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 12px 24px;
}

.search-bar__field {
  flex: 1;
  height: 46px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 15px 16px;
  border-radius: 999px;
}

/* The results area starts where the bar ends and runs to the keyboard. */
.search-results { position: absolute; top: 124px; left: 0; right: 0; padding: 16px; }
.search-results__spinner { height: 411px; display: grid; place-items: center; }

