// Eight frames, one screen. What differs is the query and which of four bodies
// the results area holds:
//
//   prompt   — the fixed line, shown under the threshold and alongside an empty result
//   spinner  — while the query runs
//   empty    — “No chats found”, with the prompt repeated beneath it
//   results  — the Chat history row, with the matched run in Semibold
//
// The keyboard is up in all eight: none of them is a state you reach by dismissing it.

code.swiftui:
// The bar is a search field and a Cancel, bottom-aligned in a 124pt header.
struct HistorySearchBar: View {
  @Binding var query: String
  var onCancel: () -> Void

  var body: some View {
    HStack(spacing: 8) {
      HStack(spacing: 8) {
        Image(systemName: "magnifyingglass")
        TextField("Search history", text: $query)
      }
      .padding(.horizontal, 16)
      .frame(height: 46)
      .background(Capsule().fill(Color(.systemGray6)))

      Button("Cancel", action: onCancel)
        .font(.system(size: 12, weight: .medium))
    }
    .padding(.horizontal, 24)
    .frame(height: 124, alignment: .bottom)
  }
}
